{
  "verdict": "CHANGES",
  "findings": [
    {
      "scope": "DIFF",
      "severity": "HIGH",
      "reference": "SendGuard.mqh, MaySend state predicate",
      "problem": "The new predicate allows a resend while the broker outcome is UNKNOWN. If the broker accepted the original request, resending before reconciliation can create duplicate exposure.",
      "example": "MaySend(UNKNOWN, 1, 3) must return false while reconciliation is pending. The new code returns true."
    },
    {
      "scope": "DIFF",
      "severity": "HIGH",
      "reference": "SendGuard.mqh, MaySend attempt limit",
      "problem": "The new guard permits attemptIndex equal to maxAttempts, allowing one extra send beyond the configured budget.",
      "example": "With maxAttempts set to 1, MaySend(READY, 0, 1) must return true and MaySend(FAILED, 1, 1) must return false. The new code returns true for both."
    }
  ]
}
